from collections import defaultdict, deque
from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def verticalOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []
        col_map = defaultdict(list)
        q = deque([(root, 0)])
        min_col = max_col = 0
        while q:
            node, col = q.popleft()
            col_map[col].append(node.val)
            min_col = min(min_col, col)
            max_col = max(max_col, col)
            if node.left:
                q.append((node.left, col - 1))
            if node.right:
                q.append((node.right, col + 1))
        return [col_map[c] for c in range(min_col, max_col + 1)]

class Solution {
public:
    vector<vector<int>> verticalOrder(TreeNode* root) {
        if (!root) return {};
        map<int, vector<int>> col_map;
        queue<pair<TreeNode*, int>> q;
        q.push({root, 0});
        while (!q.empty()) {
            auto [node, col] = q.front();
            q.pop();
            col_map[col].push_back(node->val);
            if (node->left) q.push({node->left, col - 1});
            if (node->right) q.push({node->right, col + 1});
        }
        vector<vector<int>> res;
        for (const auto& [col, vals] : col_map) {
            res.push_back(vals);
        }
        return res;
    }
};

class Solution {
    public List<List<Integer>> verticalOrder(TreeNode root) {
        if (root == null) return new ArrayList<>();
        Map<Integer, List<Integer>> colMap = new HashMap<>();
        Queue<Pair> q = new LinkedList<>();
        q.offer(new Pair(root, 0));
        int minCol = 0, maxCol = 0;
        while (!q.isEmpty()) {
            Pair p = q.poll();
            colMap.computeIfAbsent(p.col, k -> new ArrayList<>()).add(p.node.val);
            minCol = Math.min(minCol, p.col);
            maxCol = Math.max(maxCol, p.col);
            if (p.node.left != null) q.offer(new Pair(p.node.left, p.col - 1));
            if (p.node.right != null) q.offer(new Pair(p.node.right, p.col + 1));
        }
        List<List<Integer>> res = new ArrayList<>();
        for (int c = minCol; c <= maxCol; c++) {
            if (colMap.containsKey(c)) res.add(colMap.get(c));
        }
        return res;
    }
    static class Pair {
        TreeNode node;
        int col;
        Pair(TreeNode n, int c) { node = n; col = c; }
    }
}

